fn move_value(document: &mut DocumentMut, origin: &[&str], target: &[&str]) -> Result<(), String> {
    if origin.is_empty() || target.is_empty() {
        return Err("Origin and target paths must not be empty".to_string());
    }

    // Resolve the origin item
    let mut current = document;
    for key in origin {
        let item = current.get(*key)?;
        if !item.is_some() {
            return Err(format!("Origin path does not exist: {}", origin.join(".")));
        }
        current = item.as_table_like_mut().ok_or_else(|| {
            format!("Cannot navigate into non-table type at origin: {}", key)
        })?;
    }

    // Ensure the origin is a table so we can remove it
    let origin_item = current.get(origin.last().unwrap());
    let origin_item = origin_item.ok_or_else(|| {
        format!("Failed to get origin item: {}", origin.join("."))
    })?;

    let origin_table = origin_item.as_table_like_mut().ok_or_else(|| {
        format!("Origin value is not a table: {}", origin.join("."))
    })?;

    // Resolve the target path and ensure the target location exists as a table
    let mut target_current = document;
    for key in target.iter().take(target.len() - 1) {
        let item = target_current.get(*key)?;
        target_current = item.as_table_like_mut().ok_or_else(|| {
            format!("Cannot navigate into non-table type at target path: {}", key)
        })?;
    }

    // Prepare the target item name
    let target_key = target.last().unwrap();
    let target_item = target_current.get_mut(target_key);

    // Remove the value from the origin
    origin_table.remove(origin.last().unwrap()).ok_or_else(|| {
        format!("Failed to remove value from origin: {}", origin.join("."))
    })?;

    // Insert the value into the target
    if target_item.is_some() {
        // If target already exists, we can't just overwrite unless we replace the whole item
        // But per typical "move" semantics in config migration, we assume target doesn't exist or we overwrite
        // Since we are moving, we will overwrite the target key with the moved value
        let mut target_table = target_item.as_table_like_mut().ok_or_else(|| {
            format!("Target value at {} is not a table: {}", target.join("."), target_key)
        })?;
        // Clear existing content if target was a table, effectively overwriting
        target_table.clear();
        target_table.extend(origin_table.iter());
